import React from "react";
import {Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle} from "@mui/material";
import {useTranslation} from "../../../i18n";

interface IProps {
    isOpen: boolean;
    isDeleting: boolean;
    setOpen: any;
    deleteDeliveryMethod: any;
}

const DeleteModal = ({isOpen, isDeleting, setOpen, deleteDeliveryMethod}: IProps) => {
    const {t} = useTranslation();

    return (
        <Dialog
            open={isOpen}
            onClose={() => {if (!isDeleting) setOpen(false);}}
        >
            <DialogTitle>{t("Подтверждение удаления способа доставки")}</DialogTitle>
            <DialogContent>
                <DialogContentText>
                    {t("Вы действительно хотите удалить этот способ доставки из системы?")}
                </DialogContentText>
            </DialogContent>
            <DialogActions>
                <Button disabled={isDeleting} onClick={() => setOpen(false)}>{t("Отмена")}</Button>
                <Button color="error" disabled={isDeleting} onClick={() => deleteDeliveryMethod()} autoFocus>
                    {t("Удалить")}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default DeleteModal;
