import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../../api/errors";
import QueryError from "../../shared/QueryError";
import React, {useState} from "react";
import {GridRowId} from "@mui/x-data-grid";
import {NavLink} from "react-router-dom";
import AddIcon from "@mui/icons-material/Add";
import CoreButton from "../../../ui/buttons/coreButton";
import deliveryMethodColumns from "./deliveryMethodColumns";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    StyledDataGrid,
    Surface,
} from "../../../ui/commonStyled/commonStyled";
import DeleteModal from "./deleteModal";
import Loader from "../../../ui/loader/loader";
import {useDeleteDeliveryMethodMutation, useGetDeliveryMethodsQuery} from "./deliveryMethodsApi";
import {useTranslation} from "../../../i18n";

const DeliveryMethodsManagement = () => {
    const {t} = useTranslation();
    const [dmToDeleteId, setDmToDeleteId] = useState<GridRowId>();
    const [deleteModalOpen, setDeleteModalOpen] = useState(false);

    const {data: deliveryMethods = [], isLoading, isError, error, refetch} = useGetDeliveryMethodsQuery({});
    const [deleteDeliveryMethod, {isLoading: isDeleting}] = useDeleteDeliveryMethodMutation({});

    const handleSetDmToDelete = (id: GridRowId) => {
        setDeleteModalOpen(true);
        setDmToDeleteId(id);
    };

    async function deleteDeliveryMethodHandler() {
        if (isDeleting || dmToDeleteId === undefined) return;
        try {
            await deleteDeliveryMethod(dmToDeleteId).unwrap();
            toast.success(t("Способ доставки удалён."));
            setDeleteModalOpen(false);
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось удалить запись.")));
        }
    }

    if (isLoading) {
        return <Loader/>;
    }

    if (isError) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;

    return (
        <MainDiv>
            <DeleteModal
                isOpen={deleteModalOpen}
                isDeleting={isDeleting}
                setOpen={setDeleteModalOpen}
                deleteDeliveryMethod={deleteDeliveryMethodHandler}
            />

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Способы доставки")}</PageTitle>
                    <PageSubtitle>{t("Стоимость и варианты доставки для расчета заказов.")}</PageSubtitle>
                </PageTitleGroup>
                <NavLink to="createDeliveryMethod" style={{textDecoration: "none"}}>
                    <CoreButton
                        muiType="success"
                        leftIcon={<AddIcon/>}
                        text={t("Создать способ")}
                    />
                </NavLink>
            </PageHeader>

            <Surface>
                <StyledDataGrid
                    loading={isLoading}
                    pagination
                    autoHeight
                    rows={deliveryMethods}
                    columns={deliveryMethodColumns(handleSetDmToDelete, t)}
                    pageSizeOptions={[25, 50, 100]}
                    disableRowSelectionOnClick
                />
            </Surface>
        </MainDiv>
    );
};

export default DeliveryMethodsManagement;
